use personal_desk::{db::Database,export::{self,Scope},writing_images};
use std::io::Read;
#[test]
fn images_are_copied_validated_and_exported_with_usable_relative_links(){
 let temp=tempfile::tempdir().unwrap();let data=temp.path().join("data");std::fs::create_dir(&data).unwrap();let image_path=temp.path().join("图片.png");image::DynamicImage::new_rgb8(3,3).save(&image_path).unwrap();let reference=writing_images::import(&data,&image_path).unwrap();let (bytes,mime)=writing_images::read(&data,&reference).unwrap();assert_eq!(mime,"image/png");assert!(!bytes.is_empty());assert!(writing_images::read(&data,"writing-assets/../desk.db").is_err());assert!(writing_images::read(&data,"elsewhere.png").is_err());
 let mut db=Database::open(&data).unwrap();let mut page=db.create_writing("测试",None,None).unwrap();page.body=format!("![示例]({reference})");db.finish_writing_save("test",&mut page).unwrap();drop(db);let zip_path=temp.path().join("export.zip");export::write(&data,&zip_path,Scope::Documents).unwrap();let mut zip=zip::ZipArchive::new(std::fs::File::open(zip_path).unwrap()).unwrap();assert!(zip.by_name(&reference).is_ok());let mut markdown=String::new();zip.by_name(&format!("writing/{}.md",page.id)).unwrap().read_to_string(&mut markdown).unwrap();assert!(markdown.contains(&format!("../{reference}")));
}
#[test]
fn clipboard_image_bytes_are_validated_before_storage(){let temp=tempfile::tempdir().unwrap();let data=temp.path();assert!(writing_images::import_bytes(data,b"not an image").is_err());assert!(!data.join("writing-assets").exists());let path=data.join("source.png");image::DynamicImage::new_rgb8(2,2).save(&path).unwrap();let input=std::fs::read(path).unwrap();let reference=writing_images::import_bytes(data,&input).unwrap();let (stored,_)=writing_images::read(data,&reference).unwrap();assert_eq!(stored,input)}
#[test]
fn single_markdown_export_keeps_images_next_to_export_and_original_unchanged(){let root=tempfile::tempdir().unwrap();let data=root.path().join("data");let out=root.path().join("out");std::fs::create_dir(&data).unwrap();std::fs::create_dir(&out).unwrap();let source=root.path().join("source.png");image::DynamicImage::new_rgb8(2,2).save(&source).unwrap();let reference=writing_images::import(&data,&source).unwrap();let mut page=personal_desk::library::Page::new("root".into());page.title="样例".into();page.body=format!("![图片]({reference})");let dest=out.join("导出.md");writing_images::export_markdown(&data,&page,&dest).unwrap();let result=std::fs::read_to_string(&dest).unwrap();let path=result.split("](").nth(1).unwrap().split(')').next().unwrap();assert!(out.join(path).is_file());assert!(page.body.contains(&reference));assert!(writing_images::read(&data,&reference).is_ok());}
#[test]
fn export_missing_image_does_not_overwrite_destination(){let root=tempfile::tempdir().unwrap();let dest=root.path().join("existing.md");std::fs::write(&dest,"保留").unwrap();let mut page=personal_desk::library::Page::new("root".into());page.body="![图](writing-assets/missing.png)".into();assert!(writing_images::export_markdown(root.path(),&page,&dest).is_err());assert_eq!(std::fs::read_to_string(dest).unwrap(),"保留");}
